@startuml
class Animal {
    +name: String
    +age: int
    +makeSound(): void
    +move(): void
}

class Dog {
    +breed: String
    +fetch(): void
}

class Cat {
    +indoor: boolean
    +purr(): void
}

Animal <|-- Dog
Animal <|-- Cat
@enduml

@startuml
class User {
    +id: int
    +email: String
    +register(): void
    +login(): void
}

class Order {
    +id: int
    +total: Decimal
    +place(): void
    +cancel(): void
}

class Product {
    +id: int
    +name: String
    +price: Decimal
}

class OrderItem {
    +quantity: int
}

User "1" --> "*" Order : places
Order "1" *-- "*" OrderItem : contains
OrderItem "*" --> "1" Product : references
@enduml

@startuml
package "Domain" {
    class Entity {
        +id: int
    }
    class User extends Entity {
        +email: String
    }
    class Document extends Entity {
        +title: String
        +content: String
    }
}

package "Repository" {
    interface Repository<T> {
        +findById(id: int): T
        +save(entity: T): void
        +delete(id: int): void
    }
    class UserRepository implements Repository
    class DocumentRepository implements Repository
}

UserRepository ..> User
DocumentRepository ..> Document
@enduml

@startuml
start
:Receive request;
:Validate input;

if (Valid?) then (yes)
    :Process data;
    :Save to database;
    :Return success;
else (no)
    :Return error;
endif

stop
@enduml

@startuml
|Customer|
start
:Browse products;
:Add to cart;
:Checkout;

|Payment Service|
:Process payment;

if (Payment OK?) then (yes)
    |Warehouse|
    :Pick items;
    :Pack order;
    :Ship order;

    |Customer|
    :Receive order;
    stop
else (no)
    |Customer|
    :Show payment error;
    stop
endif
@enduml

@startuml
start
:Initialize build;

fork
    :Compile source;
fork again
    :Run linter;
fork again
    :Run type checker;
end fork

:Run unit tests;

if (All passed?) then (yes)
    :Build Docker image;
    :Push to registry;
    :Deploy to staging;
    stop
else (no)
    :Send failure notification;
    stop
endif
@enduml

@startuml
package "Frontend" {
    [React App] as react
    [API Client] as client
}

package "Backend" {
    [REST API] as api
    [Auth Service] as auth
    [Business Logic] as logic
}

package "Data Layer" {
    [PostgreSQL] as db
    [Redis Cache] as cache
}

react --> client
client --> api : HTTPS
api --> auth
api --> logic
logic --> db
logic --> cache
@enduml

@startuml
[*] --> Active

state Active {
    [*] --> Idle
    Idle --> Processing : receive job
    Processing --> Idle : job complete
    Processing --> Error : failure

    state Error {
        [*] --> Retrying
        Retrying --> Retrying : retry
        Retrying --> [*] : max retries
    }

    Error --> Idle : recovered
}

Active --> Shutdown : stop signal
Shutdown --> [*]
@enduml

@startuml
node "Load Balancer" as lb {
    [Nginx]
}

node "App Server 1" as app1 {
    [FastAPI]
    [Uvicorn]
}

node "App Server 2" as app2 {
    [FastAPI] as api2
    [Uvicorn] as uv2
}

node "Database Server" as dbsrv {
    database "PostgreSQL" as db
    database "Redis" as redis
}

lb --> app1 : HTTP
lb --> app2 : HTTP
app1 --> dbsrv
app2 --> dbsrv
@enduml

